-- 步骤3：对账单与对中化通知状态（ar_no 从步骤2结果取）
-- 3a. 对账单本体
SELECT ar_no, ar_type, ar_amount, bill_date, last_pay_date, record_version, create_time
FROM receivable_accounts
WHERE ar_no IN (/* 第2步查出的 ar_no 列表 */);

-- 3b. 通知记录（sys_api_request，biz_type=2 对账单通知）
-- 判读：无记录→executeNotify 未执行；status=1(INIT)长期不流转→组装明细抛异常静默失败（查 scf-saps
--       日志 error：“未匹配到运营商账单|未匹配到车辆信息|未匹配到车架号|未唯一匹配到运营商车辆账单”）；
--       status=3(FAIL) 且 retry_count=5→重试耗尽（应有企业微信告警“中化通知超过最大次数请检查”）；
--       status=4(SUCCESS)→我方已送达，转步骤4核对中化接收侧
SELECT request_sn, biz_no, biz_sub_type, status, retry_count, max_retry,
       first_request_time, modify_time, last_error_msg
FROM sys_api_request
WHERE biz_type = 2
  AND biz_no IN (/* 第3a步查出的 ar_no 列表 */)
ORDER BY biz_no, first_request_time;

-- 步骤4：中化接口侧（scf-intf-zhonghua 库）statement_notify_record
SELECT req_sn, statement_no, status, response_code, response_msg, request_time
FROM statement_notify_record
WHERE statement_no IN (/* ar_no 列表 */)
ORDER BY request_time;

-- 步骤4b.（兜底反查）清单编号是否曾出现在已推送中化的对账单明细 JSON 中（抽样即可）
SELECT req_sn, statement_no, status, response_code, request_time
FROM statement_notify_record
WHERE statement_details LIKE '%FA26031712300100010801%'
   OR statement_details LIKE '%FA26031715250100010801%'
   OR statement_details LIKE '%FA26031816300100010801%'
   OR statement_details LIKE '%FA26031820400000010801%'
   OR statement_details LIKE '%FA26031820400000010802%'
ORDER BY request_time;
